-- Catálogo de cámaras, Tanda 3: Pentax, Olympus y Minolta (Diego, 20-nov:
-- «Sí a todo»).
--
-- 198 modelos:
-- · Pentax: el archivo oficial de Ricoh (52, con año) y Wikidata (18).
-- · Olympus: su museo (17, con año) y una lista curada (48).
-- · Minolta: una lista curada (57) y Wikidata (6).
-- Tipo, formato y montura salen de la línea de cada cámara; el año solo
-- donde una fuente lo da. Cada nombre regional es su propio modelo (α, Maxxum
-- y Dynax; OM-20 y OM-G). Revisión: docs privados, TANDA-3.
--
-- La clave de un modelo lee «α» como «alpha»: sin eso, «α-7000» (Japón) y
-- «7000» (Europa) serían el mismo nombre. Ningún modelo que ya existe lleva
-- α, así que ninguna clave cambia; los índices se reconstruyen igual.

create or replace function app_private.camera_model_key(p_name text)
returns text
language sql
immutable
set search_path = ''
as $$
  select app_private.manufacturer_key(replace(lower(coalesce(p_name, '')), 'α', 'alpha'))
$$;
reindex index public.camera_models_approved_key;
reindex index public.camera_models_own_key;

insert into public.camera_models
  (manufacturer_id, name, type, format, frame_sizes, mount_id, interchangeable, year_from,
   source, source_ref, status)
select app_private.manufacturer_for(v.maker, null, true), v.name, v.type, v.format, v.frames,
       (select m.id from public.lens_mounts m where m.status = 'approved' and m.name = v.mount),
       v.interchangeable, v.year, v.source, v.ref, 'approved'
